insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-pharmacognosy-extra-mcq-01','Pharmacy','Diploma in Pharmacy','mcq','free',2001,'{"question":"Pharmacognosy is the study of:","translation":"Pharmacognosy भन्नाले केको अध्ययन बुझिन्छ?","options":["Crude drugs from natural sources","Only synthetic polymers","Hospital accounting","Medical imaging"],"correctIndex":0,"explanation":"Pharmacognosy studies crude drugs and substances obtained from natural sources, including plants, animals and minerals.","explanationNe":"Pharmacognosy ले वनस्पति, जनावर र खनिजजस्ता प्राकृतिक स्रोतबाट प्राप्त crude drugs को अध्ययन गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-02','Pharmacy','Diploma in Pharmacy','mcq','free',2002,'{"question":"The term crude drug generally refers to:","translation":"Crude drug भन्नाले सामान्यतया के बुझिन्छ?","options":["Natural drug material used with limited processing","A fully synthetic finished tablet only","A drug with no active constituents","A contaminated medicine"],"correctIndex":0,"explanation":"Crude drugs are natural materials that may be collected and processed by drying, cutting or other simple operations.","explanationNe":"Crude drug प्राकृतिक पदार्थ हो जसलाई सुकाउने, काट्ने वा सामान्य प्रशोधन गरेर प्रयोग गरिन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-03','Pharmacy','Diploma in Pharmacy','mcq','free',2003,'{"question":"Which is a plant-derived crude drug?","translation":"वनस्पतिबाट प्राप्त crude drug कुन हो?","options":["Senna leaf","Insulin from recombinant production","Sodium chloride","Paraffin wax"],"correctIndex":0,"explanation":"Senna leaves are a well-known plant-derived crude drug containing sennosides.","explanationNe":"Senna को पात वनस्पतिबाट प्राप्त crude drug हो र यसमा sennosides हुन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',2004,'{"question":"The main active constituents of senna are:","translation":"Senna का मुख्य सक्रिय constituents कुन हुन्?","options":["Sennosides","Atropine","Quinine","Morphine"],"correctIndex":0,"explanation":"Sennosides are anthraquinone glycosides responsible for senna''s stimulant laxative action.","explanationNe":"Sennosides anthraquinone glycosides हुन् र senna को stimulant laxative प्रभावका लागि जिम्मेवार हुन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',2005,'{"question":"Clove is the dried:","translation":"Clove भनेको सुकाइएको कुन भाग हो?","options":["Flower bud","Root","Fruit pulp","Bark"],"correctIndex":0,"explanation":"Clove consists of dried unopened flower buds of Syzygium aromaticum.","explanationNe":"Clove भनेको Syzygium aromaticum को नसुकेको फूलको कोपिला हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',2006,'{"question":"The major volatile oil constituent of clove is:","translation":"Clove को मुख्य volatile oil constituent कुन हो?","options":["Eugenol","Menthol","Cineole","Thymol"],"correctIndex":0,"explanation":"Eugenol is the major constituent of clove oil and contributes to its characteristic properties.","explanationNe":"Eugenol clove oil को मुख्य constituent हो र यसको विशेष गुणमा योगदान गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',2007,'{"question":"Cinchona bark is a source of:","translation":"Cinchona bark कुन पदार्थको स्रोत हो?","options":["Quinine","Digoxin","Sennoside","Reserpine"],"correctIndex":0,"explanation":"Cinchona bark contains quinoline alkaloids including quinine.","explanationNe":"Cinchona bark मा quinine लगायत quinoline alkaloids पाइन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',2008,'{"question":"Digitalis leaves contain cardiac glycosides such as:","translation":"Digitalis को पातमा कुन cardiac glycosides पाइन्छन्?","options":["Digoxin-related glycosides","Sennosides only","Tannins only","Volatile oils only"],"correctIndex":0,"explanation":"Digitalis species contain cardiac glycosides; digoxin is associated with Digitalis lanata.","explanationNe":"Digitalis प्रजातिमा cardiac glycosides हुन्छन्; digoxin Digitalis lanata सँग सम्बन्धित छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',2009,'{"question":"Ginger is the dried:","translation":"Ginger भनेको सुकाइएको कुन भाग हो?","options":["Rhizome","Leaf","Flower","Seed"],"correctIndex":0,"explanation":"Ginger is the rhizome of Zingiber officinale.","explanationNe":"Ginger भनेको Zingiber officinale को rhizome हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-10','Pharmacy','Diploma in Pharmacy','mcq','free',2010,'{"question":"Turmeric is obtained from the rhizome of:","translation":"Turmeric कुन वनस्पतिको rhizome बाट प्राप्त हुन्छ?","options":["Curcuma longa","Rauvolfia serpentina","Cinchona officinalis","Atropa belladonna"],"correctIndex":0,"explanation":"Turmeric is the rhizome of Curcuma longa and contains curcuminoids.","explanationNe":"Turmeric Curcuma longa को rhizome हो र यसमा curcuminoids पाइन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-11','Pharmacy','Diploma in Pharmacy','mcq','free',2011,'{"question":"Rauwolfia root is known for containing:","translation":"Rauwolfia को जरामा कुन constituent पाइन्छ?","options":["Reserpine","Quinine","Eugenol","Sennoside"],"correctIndex":0,"explanation":"Rauwolfia serpentina contains indole alkaloids including reserpine.","explanationNe":"Rauwolfia serpentina मा reserpine लगायत indole alkaloids पाइन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-12','Pharmacy','Diploma in Pharmacy','mcq','free',2012,'{"question":"The chief constituent of peppermint oil is commonly:","translation":"Peppermint oil को प्रमुख constituent सामान्यतया कुन हो?","options":["Menthol","Quinine","Atropine","Digoxin"],"correctIndex":0,"explanation":"Menthol is a major characteristic constituent of peppermint oil.","explanationNe":"Menthol peppermint oil को प्रमुख विशेष constituent हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-13','Pharmacy','Diploma in Pharmacy','mcq','free',2013,'{"question":"A volatile oil is also commonly called:","translation":"Volatile oil लाई अर्को के नामले चिनिन्छ?","options":["Essential oil","Fixed oil","Mineral oil","Fatty wax"],"correctIndex":0,"explanation":"Volatile oils are also called essential oils and are generally aromatic and volatile.","explanationNe":"Volatile oil लाई essential oil पनि भनिन्छ र सामान्यतया सुगन्धित तथा वाष्पशील हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-14','Pharmacy','Diploma in Pharmacy','mcq','free',2014,'{"question":"Fixed oils differ from volatile oils because fixed oils generally:","translation":"Fixed oil र volatile oil बीच मुख्य फरक के हो?","options":["Leave a persistent greasy stain and do not readily evaporate","Evaporate completely at room temperature","Are always aromatic","Contain only alkaloids"],"correctIndex":0,"explanation":"Fixed oils are non-volatile lipids and commonly leave a lasting greasy spot on paper.","explanationNe":"Fixed oil non-volatile lipid हो र कागजमा स्थायी चिल्लो दाग छोड्न सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-15','Pharmacy','Diploma in Pharmacy','mcq','free',2015,'{"question":"Alkaloids are generally:","translation":"Alkaloids सामान्यतया कस्ता पदार्थ हुन्?","options":["Basic nitrogen-containing natural compounds","Simple carbohydrates without nitrogen","Inorganic salts only","Proteins only"],"correctIndex":0,"explanation":"Many alkaloids are nitrogen-containing basic compounds with marked physiological activity.","explanationNe":"धेरै alkaloids नाइट्रोजनयुक्त क्षारीय प्राकृतिक यौगिक हुन् र शारीरिक प्रभाव देखाउँछन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-16','Pharmacy','Diploma in Pharmacy','mcq','free',2016,'{"question":"Glycosides consist of:","translation":"Glycoside कुन भागबाट बनेको हुन्छ?","options":["Sugar part and non-sugar aglycone","Two fatty acids only","Amino acids only","Mineral salts only"],"correctIndex":0,"explanation":"A glycoside contains a sugar portion linked to a non-sugar part called the aglycone or genin.","explanationNe":"Glycoside मा sugar भाग र aglycone वा genin भनिने non-sugar भाग जोडिएको हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-17','Pharmacy','Diploma in Pharmacy','mcq','free',2017,'{"question":"Tannins are known for their:","translation":"Tannins कुन गुणका लागि परिचित छन्?","options":["Astringent property","Strong sweet taste","Volatility","Radioactivity"],"correctIndex":0,"explanation":"Tannins can precipitate proteins and produce an astringent effect.","explanationNe":"Tannins ले protein precipitate गर्न सक्छन् र astringent प्रभाव दिन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-18','Pharmacy','Diploma in Pharmacy','mcq','free',2018,'{"question":"Saponins may produce:","translation":"Saponins ले कस्तो प्रभाव देखाउन सक्छन्?","options":["Foam when shaken with water","A metallic lustre","A permanent magnetic field","A strong petroleum odour"],"correctIndex":0,"explanation":"Many saponins form persistent foam in aqueous solutions because of their surface-active properties.","explanationNe":"धेरै saponins ले सतह सक्रिय गुणका कारण पानीमा हल्लाउँदा फिँज बनाउँछन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-19','Pharmacy','Diploma in Pharmacy','mcq','free',2019,'{"question":"The main storage purpose of crude drugs in a dry place is to reduce:","translation":"Crude drugs सुख्खा ठाउँमा राख्नुको मुख्य उद्देश्य के हो?","options":["Moisture-related deterioration and microbial growth","Their identity","All chemical constituents","Their medicinal classification"],"correctIndex":0,"explanation":"Excess moisture can encourage mould, enzymatic change and deterioration.","explanationNe":"अत्यधिक चिस्यानले ढुसी, enzyme परिवर्तन र गुणस्तर ह्रास बढाउन सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',2020,'{"question":"Adulteration of crude drugs means:","translation":"Crude drug adulteration भन्नाले के बुझिन्छ?","options":["Substitution or mixing with inferior, spurious or unwanted material","Correct identification and grading","Proper drying","Standard packaging"],"correctIndex":0,"explanation":"Adulteration reduces authenticity or quality by adding or substituting unsuitable material.","explanationNe":"अनुपयुक्त पदार्थ मिसाएर वा साटेर crude drug को वास्तविकता वा गुणस्तर घटाउनु adulteration हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-21','Pharmacy','Diploma in Pharmacy','mcq','free',2021,'{"question":"Macroscopy involves examination by:","translation":"Macroscopy मा कसरी परीक्षण गरिन्छ?","options":["Unaided senses and visible features","Only DNA sequencing","Only chromatography","Only infrared spectroscopy"],"correctIndex":0,"explanation":"Macroscopic evaluation examines visible characters such as size, shape, colour, odour and texture.","explanationNe":"Macroscopy मा आकार, आकृति, रङ, गन्ध र बनावटजस्ता देखिने गुण जाँचिन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-22','Pharmacy','Diploma in Pharmacy','mcq','free',2022,'{"question":"Microscopy is useful in crude drug evaluation to examine:","translation":"Crude drug मूल्याङ्कनमा microscopy ले के जाँच्छ?","options":["Cellular and tissue characters","Only retail price","Only package weight","Patient response"],"correctIndex":0,"explanation":"Microscopy can reveal diagnostic tissues, fibres, stomata, crystals and other structures.","explanationNe":"Microscopy ले पहिचानका लागि उपयोगी tissue, fibre, stomata, crystal र अन्य संरचना देखाउन सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-23','Pharmacy','Diploma in Pharmacy','mcq','free',2023,'{"question":"Ash value is commonly used to assess:","translation":"Ash value सामान्यतया के मूल्याङ्कन गर्न प्रयोग हुन्छ?","options":["Inorganic residue and possible contamination","Volatile oil aroma only","Sugar content only","Colour intensity only"],"correctIndex":0,"explanation":"Ash values help assess total inorganic residue and may indicate earthy or other inorganic contamination.","explanationNe":"Ash value ले अकार्बनिक अवशेष देखाउँछ र माटो वा अन्य अकार्बनिक दूषणको संकेत दिन सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-24','Pharmacy','Diploma in Pharmacy','mcq','free',2024,'{"question":"Foreign matter in crude drugs refers to:","translation":"Crude drug मा foreign matter भन्नाले के बुझिन्छ?","options":["Unwanted material not belonging to the specified drug","The active constituent","The correct plant part","The standard marker compound"],"correctIndex":0,"explanation":"Foreign matter includes extraneous materials such as other plant parts, soil or insects.","explanationNe":"Foreign matter मा अन्य वनस्पति भाग, माटो वा कीराहरूजस्ता अनावश्यक पदार्थ पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-25','Pharmacy','Diploma in Pharmacy','mcq','free',2025,'{"question":"Organoleptic evaluation uses:","translation":"Organoleptic evaluation मा के प्रयोग हुन्छ?","options":["Sight, smell, taste and touch where safe and appropriate","Only X-ray diffraction","Only DNA analysis","Only weighing"],"correctIndex":0,"explanation":"Organoleptic assessment uses sensory characteristics, but tasting unknown or toxic samples must be avoided.","explanationNe":"यसमा इन्द्रियबाट रङ, गन्ध, स्वाद र स्पर्श जाँचिन्छ; अज्ञात वा विषालु नमुना चाख्नु हुँदैन।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-26','Pharmacy','Diploma in Pharmacy','mcq','free',2026,'{"question":"The correct botanical name generally includes:","translation":"वनस्पतिको वैज्ञानिक नाममा सामान्यतया के हुन्छ?","options":["Genus and species","Family and colour only","Common name and country only","Plant part and dose"],"correctIndex":0,"explanation":"A binomial botanical name consists of genus and specific epithet.","explanationNe":"Binomial botanical name मा genus र species epithet हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-27','Pharmacy','Diploma in Pharmacy','mcq','free',2027,'{"question":"The plant family of senna commonly used medicinally is:","translation":"औषधीय senna कुन family मा पर्छ?","options":["Fabaceae","Solanaceae","Lamiaceae","Apiaceae"],"correctIndex":0,"explanation":"Senna species used medicinally are placed in Fabaceae.","explanationNe":"औषधीय senna प्रजाति Fabaceae family मा पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-28','Pharmacy','Diploma in Pharmacy','mcq','free',2028,'{"question":"The medicinal part of clove is:","translation":"Clove को औषधीय भाग कुन हो?","options":["Unopened flower bud","Mature root","Stem bark","Seed oil only"],"correctIndex":0,"explanation":"The dried unopened flower bud is the official crude drug part of clove.","explanationNe":"Clove को crude drug भाग सुकाइएको नसुकेको फूलको कोपिला हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-29','Pharmacy','Diploma in Pharmacy','mcq','free',2029,'{"question":"The medicinal part of ginger is:","translation":"Ginger को औषधीय भाग कुन हो?","options":["Rhizome","Leaf blade","Flower petal","Fruit seed"],"correctIndex":0,"explanation":"The rhizome is the part used as ginger crude drug.","explanationNe":"Ginger crude drug मा rhizome प्रयोग हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-30','Pharmacy','Diploma in Pharmacy','mcq','free',2030,'{"question":"The source plant of cinchona is in the genus:","translation":"Cinchona को स्रोत वनस्पति कुन genus मा पर्छ?","options":["Cinchona","Digitalis","Mentha","Senna"],"correctIndex":0,"explanation":"Cinchona bark is obtained from species of the genus Cinchona.","explanationNe":"Cinchona bark Cinchona genus का प्रजातिबाट प्राप्त हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-31','Pharmacy','Diploma in Pharmacy','mcq','free',2031,'{"question":"Collection of medicinal plants should generally be done:","translation":"औषधीय वनस्पति संकलन सामान्यतया कहिले गर्नुपर्छ?","options":["At the appropriate season and stage for the required part","At any time without identification","Only after decay","When mixed with weeds"],"correctIndex":0,"explanation":"The best collection time depends on the plant part and its active constituent profile.","explanationNe":"उपयुक्त संकलन समय वनस्पतिको भाग र सक्रिय constituent को अवस्थाअनुसार फरक हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-32','Pharmacy','Diploma in Pharmacy','mcq','free',2032,'{"question":"Drying crude drugs helps to:","translation":"Crude drug सुकाउँदा के फाइदा हुन्छ?","options":["Reduce moisture and slow deterioration","Increase microbial growth","Remove the need for identification","Guarantee absence of all toxins"],"correctIndex":0,"explanation":"Proper drying reduces moisture and helps limit enzymatic and microbial deterioration.","explanationNe":"उचित सुकाइले चिस्यान घटाएर enzyme तथा सूक्ष्मजीवका कारण हुने बिग्राइ कम गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-33','Pharmacy','Diploma in Pharmacy','mcq','free',2033,'{"question":"Excessive direct sunlight may damage some crude drugs by:","translation":"अत्यधिक प्रत्यक्ष घामले केही crude drug लाई कसरी बिगार्न सक्छ?","options":["Degrading light-sensitive constituents","Increasing purity in every case","Sterilizing all material","Preventing all oxidation"],"correctIndex":0,"explanation":"Some constituents are light-sensitive, so drying conditions should be selected to protect quality.","explanationNe":"केही constituent प्रकाशप्रति संवेदनशील हुन्छन्, त्यसैले गुणस्तर जोगाउने गरी सुकाउनुपर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-34','Pharmacy','Diploma in Pharmacy','mcq','free',2034,'{"question":"Volatile oil-containing drugs are commonly stored in:","translation":"Volatile oil भएका crude drug कसरी राख्नु उपयुक्त हुन्छ?","options":["Well-closed containers protected from heat and light","Open containers near a heater","Wet sacks in sunlight","Unlabelled open trays"],"correctIndex":0,"explanation":"Tight, suitable containers and protection from heat and light help limit loss and degradation.","explanationNe":"कसिलो उपयुक्त भाँडो तथा ताप र प्रकाशबाट सुरक्षा गर्दा तेलको ह्रास कम हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-35','Pharmacy','Diploma in Pharmacy','mcq','free',2035,'{"question":"A marker compound is used in herbal drug quality control to:","translation":"Herbal drug quality control मा marker compound किन प्रयोग हुन्छ?","options":["Help identify or standardize the material","Replace all safety testing","Prove every therapeutic claim","Determine patient age"],"correctIndex":0,"explanation":"Marker compounds support identity or consistency testing; they do not alone prove clinical efficacy.","explanationNe":"Marker compound ले पहिचान वा एकरूपता जाँच्न मद्दत गर्छ; यसले मात्र clinical efficacy प्रमाणित गर्दैन।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',2036,'{"question":"Chromatography separates mixture components based on:","translation":"Chromatography ले मिश्रणका घटकलाई कुन आधारमा छुट्याउँछ?","options":["Different distribution between stationary and mobile phases","Their package size","Patient body weight","Their country of origin"],"correctIndex":0,"explanation":"Components move differently because of their interactions with stationary and mobile phases.","explanationNe":"स्थिर र चलायमान phase सँगको फरक अन्तरक्रियाका कारण घटक फरक गतिमा सर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-37','Pharmacy','Diploma in Pharmacy','mcq','free',2037,'{"question":"A herbarium is a collection of:","translation":"Herbarium भनेको केको संग्रह हो?","options":["Preserved and documented plant specimens","Only fresh animal tissues","Finished tablets","Chemical reagents"],"correctIndex":0,"explanation":"Herbaria preserve labelled plant specimens for identification, reference and research.","explanationNe":"Herbarium मा पहिचान, सन्दर्भ र अनुसन्धानका लागि label सहितका वनस्पति नमुना सुरक्षित राखिन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-38','Pharmacy','Diploma in Pharmacy','mcq','free',2038,'{"question":"A voucher specimen helps to:","translation":"Voucher specimen ले केमा मद्दत गर्छ?","options":["Provide a verifiable reference for plant identity","Determine medicine retail price","Replace batch testing","Measure tablet hardness"],"correctIndex":0,"explanation":"A voucher specimen allows later verification of the plant used in research or collection.","explanationNe":"Voucher specimen ले अनुसन्धान वा संकलनमा प्रयोग भएको वनस्पतिको पहिचान पछि पनि पुष्टि गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-39','Pharmacy','Diploma in Pharmacy','mcq','free',2039,'{"question":"Contamination of crude drugs may occur through:","translation":"Crude drug मा contamination कसरी हुन सक्छ?","options":["Soil, microbes, pesticides or poor handling","Correct labelling only","Proper drying only","Botanical identification"],"correctIndex":0,"explanation":"Contamination may arise during cultivation, collection, processing, transport or storage.","explanationNe":"खेती, संकलन, प्रशोधन, ढुवानी वा भण्डारणका क्रममा दूषण हुन सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-40','Pharmacy','Diploma in Pharmacy','mcq','free',2040,'{"question":"Good agricultural and collection practices support:","translation":"Good agricultural and collection practices ले केमा सहयोग गर्छ?","options":["Consistent quality and traceability of herbal materials","Uncontrolled mixing of species","Avoidance of all documentation","Harvesting without identification"],"correctIndex":0,"explanation":"Good practices improve identification, harvesting, handling, documentation and traceability.","explanationNe":"राम्रो अभ्यासले पहिचान, संकलन, ह्यान्डलिङ, अभिलेख र traceability सुधार गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mcq-41','Pharmacy','Diploma in Pharmacy','mcq','free',2041,'{"question":"Why should poisonous medicinal plants be handled carefully?","translation":"विषालु औषधीय वनस्पति सावधानीपूर्वक किन ह्यान्डल गर्नुपर्छ?","options":["They may contain potent toxic constituents","They are always harmless when natural","They cannot be absorbed","They have no active chemicals"],"correctIndex":0,"explanation":"Natural origin does not guarantee safety; some plants contain potent toxic compounds.","explanationNe":"प्राकृतिक स्रोत हुनु सुरक्षित हुनुको ग्यारेन्टी होइन; केही वनस्पतिमा शक्तिशाली विषालु यौगिक हुन्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-01','Pharmacy','Diploma in Pharmacy','mock','free',2101,'{"question":"Define pharmacognosy and state its scope.","answer":"Pharmacognosy is the study of crude drugs and natural products from plant, animal, microbial and mineral sources. It includes identification, cultivation, collection, processing, evaluation, constituents and quality control.","answerNe":"Pharmacognosy भनेको वनस्पति, जनावर, सूक्ष्मजीव र खनिज स्रोतका crude drugs तथा natural products को अध्ययन हो। यसमा पहिचान, खेती, संकलन, प्रशोधन, मूल्याङ्कन, constituent र quality control पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-02','Pharmacy','Diploma in Pharmacy','mock','free',2102,'{"question":"What is a crude drug? Give four examples.","answer":"A crude drug is a natural material used medicinally with limited processing. Examples include senna leaf, clove flower bud, ginger rhizome and cinchona bark.","answerNe":"Crude drug भनेको सामान्य प्रशोधनपछि औषधीय रूपमा प्रयोग हुने प्राकृतिक पदार्थ हो। उदाहरण: senna पात, clove फूलको कोपिला, ginger rhizome र cinchona bark।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-03','Pharmacy','Diploma in Pharmacy','mock','free',2103,'{"question":"Differentiate organized and unorganized crude drugs.","answer":"Organized drugs retain recognizable plant or animal cellular structure, such as leaves, roots, bark and seeds. Unorganized drugs are materials such as gums, resins, latex or dried extracts without a distinct organ structure.","answerNe":"Organized crude drug मा पात, जरा, बोक्रा र बीउजस्ता पहिचान गर्न सकिने संरचना रहन्छ। Unorganized मा gum, resin, latex वा extract जस्ता स्पष्ट अंग संरचना नहुने पदार्थ पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-04','Pharmacy','Diploma in Pharmacy','mock','free',2104,'{"question":"Describe the source, part used and major constituent of clove.","answer":"Clove is the dried unopened flower bud of Syzygium aromaticum. Its volatile oil contains eugenol as a major constituent.","answerNe":"Clove Syzygium aromaticum को सुकाइएको नसुकेको फूलको कोपिला हो। यसको volatile oil मा eugenol मुख्य constituent हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-05','Pharmacy','Diploma in Pharmacy','mock','free',2105,'{"question":"Describe senna as a crude drug.","answer":"Senna consists of dried leaflets or pods of Senna species. It contains sennosides, anthraquinone glycosides with stimulant laxative action. Quality, dose and safety require appropriate standards and advice.","answerNe":"Senna मा Senna प्रजातिका सुकाइएका पात वा फलिका हुन्छन्। यसमा stimulant laxative प्रभाव भएका anthraquinone glycosides sennosides पाइन्छन्। गुणस्तर, मात्रा र सुरक्षा उपयुक्त मापदण्ड तथा सल्लाहअनुसार हुनुपर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-06','Pharmacy','Diploma in Pharmacy','mock','free',2106,'{"question":"Write a short note on cinchona bark.","answer":"Cinchona bark is obtained from Cinchona species and contains quinoline alkaloids, notably quinine. It is an important pharmacognostic example of an alkaloid-containing bark.","answerNe":"Cinchona bark Cinchona प्रजातिबाट प्राप्त हुन्छ र यसमा quinine लगायत quinoline alkaloids हुन्छन्। यो alkaloid भएको bark को महत्त्वपूर्ण उदाहरण हो।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-07','Pharmacy','Diploma in Pharmacy','mock','free',2107,'{"question":"Describe the source and importance of ginger.","answer":"Ginger is the rhizome of Zingiber officinale. It contains pungent constituents such as gingerols and is used as a spice and in traditional preparations; quality depends on identity and processing.","answerNe":"Ginger Zingiber officinale को rhizome हो। यसमा gingerols जस्ता pungent constituent हुन्छन् र मसला तथा परम्परागत तयारीमा प्रयोग हुन्छ; गुणस्तर पहिचान र प्रशोधनमा निर्भर हुन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-08','Pharmacy','Diploma in Pharmacy','mock','free',2108,'{"question":"What are alkaloids? Give examples of plant sources.","answer":"Alkaloids are a diverse group of naturally occurring nitrogen-containing compounds, often basic and physiologically active. Examples include quinine from Cinchona and reserpine from Rauvolfia.","answerNe":"Alkaloids प्राकृतिक रूपमा पाइने नाइट्रोजनयुक्त यौगिकहरूको समूह हो, धेरैजसो क्षारीय र शारीरिक रूपमा सक्रिय हुन्छन्। उदाहरण: Cinchona बाट quinine र Rauvolfia बाट reserpine।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-09','Pharmacy','Diploma in Pharmacy','mock','free',2109,'{"question":"Explain glycosides and their basic structure.","answer":"Glycosides contain a sugar portion called the glycone linked to a non-sugar portion called the aglycone or genin. Hydrolysis may split these portions depending on the glycoside and conditions.","answerNe":"Glycoside मा glycone भनिने sugar भाग र aglycone वा genin भनिने non-sugar भाग जोडिएको हुन्छ। अवस्था र glycoside अनुसार hydrolysis हुँदा यी भाग छुट्टिन सक्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-10','Pharmacy','Diploma in Pharmacy','mock','free',2110,'{"question":"Describe the main methods used to evaluate crude drugs.","answer":"Evaluation may include organoleptic, macroscopic, microscopic, physicochemical, chemical, chromatographic and biological tests, along with checks for foreign matter and contaminants.","answerNe":"Crude drug मूल्याङ्कनमा organoleptic, macroscopic, microscopic, physicochemical, chemical, chromatographic र biological परीक्षण तथा foreign matter र contaminant जाँच पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-11','Pharmacy','Diploma in Pharmacy','mock','free',2111,'{"question":"Differentiate macroscopic and microscopic evaluation.","answer":"Macroscopy examines visible features such as size, shape, colour, odour and texture. Microscopy examines diagnostic cellular and tissue structures.","answerNe":"Macroscopy ले आकार, आकृति, रङ, गन्ध र बनावटजस्ता देखिने गुण जाँच्छ। Microscopy ले पहिचानका लागि उपयोगी कोशिका र tissue संरचना जाँच्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-12','Pharmacy','Diploma in Pharmacy','mock','free',2112,'{"question":"What is adulteration of crude drugs? Mention its effects.","answer":"Adulteration is substitution or mixing with inferior, spurious or unwanted material. It can reduce identity, purity, potency, safety and therapeutic reliability.","answerNe":"Adulteration भनेको कमसल, नक्कली वा अनावश्यक पदार्थ मिसाउनु वा साट्नु हो। यसले पहिचान, शुद्धता, potency, सुरक्षा र औषधीय विश्वसनीयता घटाउन सक्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-13','Pharmacy','Diploma in Pharmacy','mock','free',2113,'{"question":"Explain the importance of proper collection and drying of medicinal plants.","answer":"Collection at the correct season and growth stage can preserve desired constituents. Appropriate drying reduces moisture and limits enzymatic, microbial and chemical deterioration.","answerNe":"उचित मौसम र वृद्धि अवस्थाको संकलनले चाहिएका constituent जोगाउन सक्छ। उचित सुकाइले चिस्यान घटाई enzyme, सूक्ष्मजीव र रासायनिक बिग्राइ कम गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-14','Pharmacy','Diploma in Pharmacy','mock','free',2114,'{"question":"State suitable storage precautions for volatile oil-containing crude drugs.","answer":"Use well-closed compatible containers, protect from heat and light, avoid unnecessary exposure to air and moisture, and label and store under suitable conditions.","answerNe":"कसिलो र अनुकूल भाँडो प्रयोग गर्ने, ताप र प्रकाशबाट जोगाउने, हावा र चिस्यानको अनावश्यक सम्पर्क घटाउने तथा सही label सहित उपयुक्त अवस्थामा राख्ने।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-15','Pharmacy','Diploma in Pharmacy','mock','free',2115,'{"question":"What are ash value and extractive value used for?","answer":"Ash value helps assess inorganic residue and possible contamination. Extractive value estimates the amount of constituents extracted by a specified solvent under defined conditions.","answerNe":"Ash value ले अकार्बनिक अवशेष र सम्भावित दूषण जाँच्छ। Extractive value ले निश्चित अवस्थामा तोकिएको solvent बाट निकाल्न सकिने constituent को मात्रा अनुमान गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-16','Pharmacy','Diploma in Pharmacy','mock','free',2116,'{"question":"Explain the role of chromatography in herbal drug analysis.","answer":"Chromatography separates mixture components through their different interactions with stationary and mobile phases. It can support identification, fingerprinting and consistency testing.","answerNe":"Chromatography ले stationary र mobile phase सँगको फरक अन्तरक्रियाबाट मिश्रणका घटक छुट्याउँछ। यसले पहिचान, fingerprinting र एकरूपता जाँच्न सहयोग गर्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-17','Pharmacy','Diploma in Pharmacy','mock','free',2117,'{"question":"What is a marker compound? State one limitation.","answer":"A marker is a constituent selected to help identify or standardize a herbal material. Its presence or amount alone does not prove clinical efficacy or complete safety.","answerNe":"Marker compound herbal material पहिचान वा standardize गर्न छानिएको constituent हो। यसको उपस्थिति वा मात्रा मात्रले clinical efficacy वा पूर्ण सुरक्षा प्रमाणित गर्दैन।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-18','Pharmacy','Diploma in Pharmacy','mock','free',2118,'{"question":"What is a herbarium and why is a voucher specimen useful?","answer":"A herbarium stores documented plant specimens. A voucher specimen provides a reference that allows the identity of a plant used in a study or collection to be checked later.","answerNe":"Herbarium मा अभिलेखसहितका वनस्पति नमुना राखिन्छन्। Voucher specimen ले अध्ययन वा संकलनमा प्रयोग भएको वनस्पतिको पहिचान पछि जाँच्न सन्दर्भ दिन्छ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-19','Pharmacy','Diploma in Pharmacy','mock','free',2119,'{"question":"Mention important sources of contamination in crude drugs and ways to reduce them.","answer":"Contamination may arise from soil, microbes, insects, pesticides, heavy metals, poor drying or storage. Correct identification, clean handling, suitable drying, testing and protected storage reduce risk.","answerNe":"माटो, सूक्ष्मजीव, कीरा, pesticide, heavy metal, खराब सुकाइ वा भण्डारणबाट दूषण हुन सक्छ। सही पहिचान, सफा ह्यान्डलिङ, उचित सुकाइ, परीक्षण र सुरक्षित भण्डारणले जोखिम घटाउँछ।"}'::jsonb,true),
('dph-pharmacognosy-extra-mock-20','Pharmacy','Diploma in Pharmacy','mock','free',2120,'{"question":"Why does natural origin not always mean a drug is safe?","answer":"Natural materials may contain potent toxic constituents, vary in strength, be contaminated or interact with medicines. Correct identification, quality control and professional guidance are essential.","answerNe":"प्राकृतिक पदार्थमा शक्तिशाली विषालु constituent हुन सक्छ, शक्ति फरक हुन सक्छ, दूषण वा औषधिसँग interaction हुन सक्छ। सही पहिचान, quality control र विशेषज्ञ सल्लाह आवश्यक हुन्छ।"}'::jsonb,true)
